def mark_load_bl(apps, schema_editor):
    """The BL already made from a load (D-160) get their delivery status (D-178). A draft keeps its draft number and
    prints as provisional until delivered; it is to deliver."""
    Sale = apps.get_model("sales", "Sale")
    SaleLine = apps.get_model("sales", "SaleLine")
    loads = Sale.objects.filter(transfer__isnull=False)
    loads.filter(status="draft").update(delivery_status="to_deliver")
    loads.filter(status="confirmed").update(delivery_status="delivered", delivered_at=F("confirmed_at"))
    loads.filter(status="cancelled").update(delivery_status="cancelled")
    SaleLine.objects.filter(sale__transfer__isnull=False).update(ordered_quantity=F("quantity"))



